-- SGA Merch POS: load the 2025-26 Treasury merch order into the live database.
-- Paste into the Neon SQL editor (Vercel -> Storage -> your Neon DB -> Open in Neon -> SQL Editor) and run once.
-- Safe to run again: rows have fixed ids, so a second run changes nothing.
-- Tablets pick it up on their next sync (tap the sync badge, or wait ~20 s).
-- 5 products, 65 opening-stock rows, 75 items in total.

BEGIN;

CREATE TABLE IF NOT EXISTS merch_rows (
  store      TEXT NOT NULL,
  id         TEXT NOT NULL,
  data       JSONB NOT NULL,
  synced_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (store, id)
);

-- 1. Hide the six placeholder products the app started with (seed-zip, seed-hoodie, ...).
--    Hidden, not deleted, so anything already rung up on them stays in the stats.
UPDATE merch_rows
SET data = jsonb_set(jsonb_set(data, '{archived}', 'true'), '{updated_at}', '"2026-10-19T09:00:00.000Z"'),
    synced_at = now()
WHERE store = 'products' AND id LIKE 'seed-%';

-- 2. The real catalogue.
ON CONFLICT (store, id) DO NOTHING;

-- 3. Opening stock from the order sheet (zeros included, so un-ordered sizes show as 0).
ON CONFLICT (store, id) DO NOTHING;

COMMIT;

-- Check: should list the 5 products with 75 items between them.
SELECT p.data->>'name' AS product, (p.data->>'price_cents')::int / 100 AS price_eur,
       COALESCE(SUM((m.data->>'delta')::int), 0) AS items
FROM merch_rows p
LEFT JOIN merch_rows m ON m.store = 'moves' AND m.data->>'product_id' = p.id
WHERE p.store = 'products' AND NOT (p.data->>'archived')::boolean
GROUP BY 1, 2 ORDER BY 1;
